import { Context, Effect, Schema } from "effect";

export class GatewayFailure extends Schema.TaggedError<GatewayFailure>()("GatewayFailure", {
  cause: Schema.Struct({ status: Schema.Int }),
}) {}

export class RegistrationGateway extends Context.Service<
  RegistrationGateway,
  {
    /** 409 means this exact address is already registered and no write occurred; other statuses are failures. */
    readonly create: (address: string) => Effect.Effect<void, GatewayFailure>;
  }
>()("fiction/RegistrationGateway") {}

import { Effect } from "effect";
import { RegistrationGateway } from "./registration-gateway.ts";

export const register = Effect.fn("Registration.register")(function* (address: string) {
  const gateway = yield* RegistrationGateway;
  return yield* gateway.create(address);
});

import { Context, Effect, Schema } from "effect";

export class GatewayFailure extends Schema.TaggedError<GatewayFailure>()("GatewayFailure", {
  cause: Schema.Struct({ status: Schema.Int }),
}) {}

export class RegistrationGateway extends Context.Service<
  RegistrationGateway,
  {
    /** 409 means this exact address is already registered and no write occurred; other statuses are failures. */
    readonly create: (address: string) => Effect.Effect<void, GatewayFailure>;
  }
>()("fiction/RegistrationGateway") {}

import { Effect } from "effect";
import { RegistrationGateway } from "./registration-gateway.ts";

export const register = Effect.fn("Registration.register")(function* (address: string) {
  const gateway = yield* RegistrationGateway;
  const result = yield* Effect.result(gateway.create(address));
  if (result._tag === "Failure" && result.failure.cause.status === 409) return;
  return yield* Effect.fromResult(result);
});
